export type WorldName = keyof typeof WORLDS_DATA;
export const WORLD_NAMES = Object.keys(WORLDS_DATA) as WorldName[];
export const WORLDS_SORTED_BY_RELEASE = WORLD_NAMES.slice().sort(
  (a, b) => WORLDS_DATA[a].release - WORLDS_DATA[b].release
);

/**
 * Comparator that orders worlds by the canonical project sequence
 * (WORLDS_SORTED_BY_RELEASE — Newcrest → Oasis Springs → Willow Creek → …
 * by release order). Unknown world names fall back to alphabetical and sort
 * after known worlds. Use this for ANY user-facing list of worlds so the
 * order is consistent everywhere.
 */
export function compareWorldsCanonical(a: string, b: string): number {
  const ai = (WORLDS_SORTED_BY_RELEASE as readonly string[]).indexOf(a);
  const bi = (WORLDS_SORTED_BY_RELEASE as readonly string[]).indexOf(b);
  if (ai === -1 && bi === -1) return a.localeCompare(b);
  if (ai === -1) return 1;
  if (bi === -1) return -1;
  return ai - bi;
}

export const HIDDEN_LOT_TYPES = new Set([
  'The Magic Realm',
  'Secret Lot',
  "Hermit's Hut",
  'Secret Lab',
  'Acting Studio',
  'Alien Party Lot',
  'FutureSim Labs',
  'Mount Komorebi Summit',
  'Headless Quarter',
  'Ancient Ruins',
  'Auditorium',
  'High School',
  'Hospital',
  'Police Station',
  'Island Bluff',
  'Chalet Gardens',
  'Center Park',
]);

export const VISIBLE_HIDDEN_LOT_TYPES = new Set([
  'Police Station',
  'Hospital',
  'High School',
  'Auditorium',
  'Island Bluff',
  'Chalet Gardens',
  'Center Park',
  'Ancient Ruins',
  'Secret Lab',
  'Mount Komorebi Summit',
]);

export function isLotVisible(defaultType: string): boolean {
  if (!HIDDEN_LOT_TYPES.has(defaultType)) return true;
  return VISIBLE_HIDDEN_LOT_TYPES.has(defaultType);
}

/**
 * How many lots the planner actually SHOWS for a world — the set the world page
 * lists and the map pins, which are the same set.
 *
 * Not `WORLDS_DATA[w].lots.length`: that counts the game's non-plannable hidden
 * lots too (Sylvan Glade, the Forgotten Grotto, the Magic Realm, Sixam, the
 * hermit's hut, the acting studio, FutureSim Labs, the Netherworld), so the
 * sidebar used to advertise 22 lots for Willow Creek beside a page reading
 * "21 lots" — and likewise for Oasis Springs, Magnolia Promenade, Del Sol
 * Valley, Granite Falls, Glimmerbrook and Ravenwood. The editable specials
 * (Police Station, Hospital, High School, the Komorebi summit, …) DO count:
 * they're on the map and you can plan them.
 */
export const WORLD_LOT_COUNTS: Record<WorldName, number> = Object.fromEntries(
  WORLD_NAMES.map((w) => [w, WORLDS_DATA[w].lots.filter((l) => isLotVisible(l.type)).length]),
) as Record<WorldName, number>;

/**
 * The heading to show for a lot's neighbourhood.
 *
 * `location` is game data, and it carries an internal placeholder — **"Hidden
 * Lot"** — for lots that belong to no neighbourhood: Magnolia Promenade's
 * Police Station and Willow Creek Hospital, and Mt. Komorebi's Peak. Shown raw
 * it read as a place the player had never heard of, and not only in the planner:
 * the same string builds the section headings on the PUBLIC showcase.
 *
 * "Other" is the word the world page already fell back to for a lot with no
 * location at all, so this reuses it rather than coining a term.
 *
 * DISPLAY-ONLY. The stored value is untouched, so neighbourhood captions — keyed
 * `world::location` — keep resolving. Call this at the point of render, and keep
 * the raw value as the key.
 */
export const NO_NEIGHBORHOOD_LABEL = 'Other';

export function neighborhoodLabel(location: string | null | undefined): string {
  if (!location || location === 'Hidden Lot') return NO_NEIGHBORHOOD_LABEL;
  return location;
}

// Derives the building name from an apartment unit's lot name. The Sims uses two
// conventions, so we handle both:
//   - leading unit token (San Myshuno, Ondarion): "17 Bright Cliff" → "Bright Cliff",
//     "2A Jasmine Suites" → "Jasmine Suites", "1313 21 Chic Street" → "21 Chic Street"
//   - trailing "#N" unit (Evergreen Harbor): "Pinecrest Apartments #404" → "Pinecrest Apartments"
// Without the trailing-# case, Evergreen units each became their own bogus
// "Apartments #404" building and never grouped under one pin.
export function getBuildingName(lotName: string): string {
  const suffix = lotName.match(/^(.+?)\s+#\d+$/);
  if (suffix) return suffix[1];
  const prefix = lotName.match(/^\S+\s+(.+)$/);
  return prefix ? prefix[1] : lotName;
}

export type LotCategory = 'home' | 'rental' | 'venue';

export function getLotCategory(type: string): LotCategory {
  if (['Residential', 'Residential Rental', 'Apartment', 'Haunted House', 'Tiny Home Residential', 'Penthouse'].includes(type)) return 'home';
  if (['Rental', 'Vacation Rental'].includes(type)) return 'rental';
  return 'venue';
}

// How many households a home lot can hold. A "Residential Rental" (For Rent)
// lot houses several households across its rental units; every other home type
// is single-occupancy (each apartment unit is its own lot in the planner).
export function maxHouseholdsForLot(type: string): number {
  return type === 'Residential Rental' ? 6 : 1;
}

// Lot types a club can NOT set as its hangout. Confirmed with the project owner
// (see docs/planner-coherence-invariants.md, C2): plain Rental and Vacation
// Rental (transient stays) and University Housing (student dorms) can't host a
// club hangout; Apartments and Residential Rentals CAN. Single source of truth —
// both the club manager and the lot editor import this.
export const CLUB_INELIGIBLE_LOT_TYPES = new Set<string>([
  'Rental',
  'Vacation Rental',
  'University Housing',
]);

export function isClubHangoutEligible(type: string): boolean {
  return !CLUB_INELIGIBLE_LOT_TYPES.has(type);
}

// The home types a sim can run a business out of: a lot their household OWNS and
// lives on. Every home type qualifies EXCEPT Residential Rental, where they're a
// tenant rather than the owner. An apartment counts — you can run a business from
// the apartment you live in, even though an apartment can never be BOUGHT and
// converted into a Small Business Venue (see canConvertToSmallBusinessVenue).
// Confirmed by the project owner against the in-game purchase rules.
export const SB_OWN_LOT_TYPES = new Set<string>([
  'Residential',
  'Tiny Home Residential',
  'Apartment',
  'Penthouse',
  'Haunted House',
]);

/** Can a household run a HOME business here — is this a lot they own and live on? */
export function isHomeBusinessLot(type: string): boolean {
  return SB_OWN_LOT_TYPES.has(type);
}

// Lot types a small business can occupy at all (coherence invariant B1): the
// owner's own home (above), or a dedicated Small Business Venue — the type any
// other lot takes when it's bought for a business (absentee owner OK, B3).
// Single source of truth — the lot editor, the businesses page and the re-sync
// yield all import this, so widening it here widens all three at once.
export const SB_ELIGIBLE_LOT_TYPES = new Set<string>([...SB_OWN_LOT_TYPES, 'Small Business Venue']);

export function isSmallBusinessEligible(type: string): boolean {
  return SB_ELIGIBLE_LOT_TYPES.has(type);
}

// Whether an empty lot can be turned into a dedicated Small Business Venue
// (coherence B3 / the owner-first "dedicated" path). Per the game rules: any
// EMPTY lot except apartment units and student housing (University Housing),
// and excluding the hidden special lots (Komorebi Summit, Hospital, secret lots,
// …). Occupied lots are excluded — converting one would evict its household, so
// we never offer it (this also keeps occupied Residential Rentals out).
export function canConvertToSmallBusinessVenue(lot: {
  customType: string;
  defaultType: string;
  householdIds: string[];
}): boolean {
  if (lot.householdIds.length > 0) return false;
  if (lot.defaultType === 'Apartment' || lot.defaultType === 'University Housing') return false;
  // Special functional lots (Hospital, Police Station, High School, Komorebi
  // Summit, secret lots, …) can't become a business — the full hidden set, incl.
  // the ones that are otherwise visible in the type picker.
  if (HIDDEN_LOT_TYPES.has(lot.defaultType)) return false;
  return true;
}

// Lot category palette — "Recharged classic + hot pink" direction. Two colors
// per category: `tint` for soft surfaces (pill bg, pin fill, cover gradient
// placeholder), `ink` for text/border at high contrast against the tint.
//
// Home → crisp blue, Rental → orange, Venue → hot pink.
export const CATEGORY_COLORS: Record<LotCategory, string> = {
  home:   '#3c72c4',
  rental: '#e07b24',
  venue:  '#d4488e',
};

export const CATEGORY_INK: Record<LotCategory, string> = {
  home:   '#234a85',
  rental: '#8c4310',
  venue:  '#8a2058',
};

/**
 * Which table a lot type belongs to on Home's Lot Types tab.
 *
 * The game's special lots — the Police Station, the hospital, the high school,
 * the Komorebi summit — are plannable and appear on their world pages, but they
 * aren't venues anyone builds, so they gather under **Other**: the same word the
 * world page already uses for a lot that belongs to no neighbourhood.
 */
export type LotTypeSection = LotCategory | 'other';

export function getLotTypeSection(type: string): LotTypeSection {
  return HIDDEN_LOT_TYPES.has(type) ? 'other' : getLotCategory(type);
}

// Inside the Home table the game's own progression reads better than
// alphabetical; everywhere else alphabetical is what people scan by.
const HOME_TYPE_ORDER = ['Residential', 'Residential Rental', 'Apartment', 'Penthouse'];

export function compareLotTypes(a: string, b: string): number {
  const ai = HOME_TYPE_ORDER.indexOf(a);
  const bi = HOME_TYPE_ORDER.indexOf(b);
  if (ai !== -1 && bi !== -1) return ai - bi;
  if (ai !== -1) return -1;
  if (bi !== -1) return 1;
  return a.localeCompare(b);
}

const EXTRA_LOT_TYPES: string[] = ['Generic', 'Haunted House', 'Restaurant', 'Spa', 'Tiny Home Residential'];

export function getAllLotTypes(): string[] {
  const types = new Set<string>(EXTRA_LOT_TYPES);
  for (const world of Object.values(WORLDS_DATA)) {
    for (const lot of world.lots) {
      if (!HIDDEN_LOT_TYPES.has(lot.type)) types.add(lot.type);
    }
  }
  return Array.from(types).sort();
}

